window.POETRY_REGISTER("v5-extra-11-10-0-eddb81ca7f69.js",{"poems":[[52300,2],[54333,2],[54339,2],[55657,2],[57581,2],[58012,2],[132913,7],[134281,7],[236005,7],[236013,7],[271951,7],[288132,7],[297794,7],[314238,7],[354652,9],[361351,9],[368306,10],[375294,10],[380143,10],[381853,0],[439173,8],[452697,8],[453995,8],[473779,8],[488526,8],[510328,8],[552516,8],[571407,8],[596186,8],[630407,8],[650074,5],[650378,5],[653286,5],[653889,5],[660814,5],[705461,5],[712119,5],[735220,5],[739676,20]],"pairs":[["皆刻于青田之石门洞崖壁","前人录金石者皆未之及",0],["唐右拾遗内供奉王希明撰","固无丹元子隋人之说也",1],["吴郡守兼江东采访使张愿","所历名山观瀑布者多矣",2],["时光启二年冬首中旬有七","横峰先生永阳子杜希遁",3],["但皆为唐或唐以前人之作","今姑录存于杜光庭名下",4],["大中玖年正月廿八日书记","大中拾年拾日参造鼓价",5],["但闻仙童玉女语笑之清音","君不见当时匡续断世故",6],["繁霜雪霁能邀夜月来高穹","又不见江头龟手洴澼絖",7],["高者君之气兮清为君之神","君挟此以生兮不隘以大",8],["曾不知结绳与秉钺兮何时","瞻言千载兮忽焉其远而",9],["拒佞幸之请而杜亵取之门","则片言只字之落人间者",10],["安于一实兮岂斯世之足语","天何赋之厚兮而夺之遽",11],["长生之学虚荒诞幻无可冯","君不见嬴政入海采灵药",12],["焉能流涕被面日日别知己","又尝笑朝鲜无泪可沾巾",13],["参旗玉井闪闪上下随跻攀","君不闻木皮冈前九折坂",14],["下有三万六千顷之白银浆","中有美人兮佩服金鸳鸯",15],["慎莫脱手踊跃逝去双龙精","君不见我家古铁三尺冰",16],["往者不可悔兮来者不可期","进无益于世兮退将安归",17],["超然高洁兮日与云而相邻","步虚九天上兮不沾世氛",18],["所离不降兮以泄我王气苏","三军一飞降兮所向皆殂",19],["我语天风兮莫吹彼树上乌","彼乌能反哺哑哑引其雏",20],["时与谢家孙子画里心神融","君不见黄头马下三尺水",21],["君非淟涊暗穆取位之丈夫","余亦岂卑卑与世而浮沉",22],["一日不醉令我行步如龙钟","君不见泗上亭长隆准公",23],["孰不南奔兮胡独甘乎镝铓","曰君辱臣死兮惟义之常",24],["不与杨梅庐橘争献承明庐","独不闻苏子当年有至论",25],["彼物胡为处此与我争水邦","君不见鱼乱繇来从罟设",26],["患蹇捋锄兮曷返质乎空山","视世奚悲兮嗟嗟乎尔兰",27],["但见苍梧惨澹鼓瑟悲湘灵","吾闻地有五岳犹天五行",28],["患蹇捋锄兮曷返质乎空山","视世奚悲兮嗟嗟乎尔兰",29],["老牛耕地使死倒把皮来剥","河里的游鱼犯下什么罪",30],["黑洞洞的本帐簿那里去查","好兴致时来顽铁黄金色",30],["纵有那几串铜钱你慢扎煞","俺虽无临潼关的无价宝",30],["鼓弄着百姓结网打净了湾","自古道牝鸡司晨家业败",30],["等着他桑林摆桌铺起龙坛","更可笑剪爪当牲来祷告",30],["直等到太白旗悬才把口吧","老纣王倘然留得一口气",30],["朝歌地重新扎起了商家营","姜太公杀花老眼溜了阵",30],["直杀的血流漂杵堵了城门","眼见他一刀两断君臣定",30],["小胡亥忤逆贼达又是祸苗","老始皇欹在灵床没眼泪",30],["到临死卖履分香丢尽了丑","原是个老婆队里碜东西",30],["这件事比鳖不如还低一扎","不转眼则天戴了冲天帽",30],["他自己的腔像也难把口夸","洗儿钱亲自递在杨妃手",30],["不转眼生铁又在火灰上爬","石敬瑭夺了他丈人的碗",30],["那柴家的孩子他懂的什么","你看他作张作致装没事",30],["陆秀夫死葬鱼腹当了什么","说不尽大宋无寸干净土",30],["出庙门便有些英雄入网罗","不光是徐常沐邓称猛将",30],["纵居那绮罗丛中谁知娇养","幸生来英豪阔大宽宏量",31],["但愿酒人一世二世传无穷","令千秋万岁酒氏之子孙",32],["畜尔惟有刘黄高左五侯耳","君不见师延靡靡濮上水",33],["安得布袜青鞋盘桓于尔侧","彷佛乎桂殳木客之高踪",34],["我谓黄帝骑龙仙去惨不乐","君不见桥山姬水两无涉",35],["因之疫氛传染广大而无边","有父老疾首蹙额而相告",36],["纵居那绮罗丛中谁知娇养","幸生来英豪阔大宽宏量",37],["何如命驾季鹰吴中煮莼羹","又不见姜侯设鲙凿冰裂",38]]});
